<?php require __DIR__.'/../src/DependencyService.php';$u=requireLogin();$c=db();$projectId=(int)($_REQUEST['project_id']??0);if(!$projectId){$r=queryParams($c,'SELECT project_id FROM project_members WHERE user_id=$1 ORDER BY project_id LIMIT 1',[(string)$u['id']]);$projectId=(int)(pg_fetch_result($r,0,0)?:0);}if($projectId)requireProjectAccess($c,$projectId,$u);$err='';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$projectId=(int)$_POST['project_id'];requireProjectAccess($c,$projectId,$u);try{DependencyService::add($c,$projectId,(int)$_POST['issue_id'],(int)$_POST['depends_on_id']);audit($c,$projectId,(int)$u['id'],'dependency_added','issue',(int)$_POST['issue_id'],['depends_on'=>(int)$_POST['depends_on_id']]);$msg='Đã thêm quan hệ phụ thuộc.';}catch(Throwable $e){$err=$e->getMessage();}}$issues=pg_fetch_all(queryParams($c,'SELECT id,title,status FROM issues WHERE project_id=$1 ORDER BY id',[(string)$projectId]))?:[];$deps=pg_fetch_all(queryParams($c,'SELECT d.issue_id,d.depends_on_id,a.title issue_title,b.title dependency_title,b.status dependency_status FROM dependencies d JOIN issues a ON a.id=d.issue_id JOIN issues b ON b.id=d.depends_on_id WHERE a.project_id=$1 ORDER BY d.issue_id',[(string)$projectId]))?:[];$blocked=pg_fetch_all(queryParams($c,"SELECT a.id,a.title,b.id blocked_by_id,b.title blocked_by FROM dependencies d JOIN issues a ON a.id=d.issue_id JOIN issues b ON b.id=d.depends_on_id WHERE a.project_id=$1 AND b.status NOT IN ('verified','closed') ORDER BY a.id",[(string)$projectId]))?:[];pageStart('Quan hệ phụ thuộc');if($err)echo '<p class="error">'.h($err).'</p>';if($msg)echo '<p class="ok">'.h($msg).'</p>';?><section class="panel"><h2>Thêm quan hệ phụ thuộc</h2><p class="muted">A phụ thuộc B nghĩa là B cần hoàn thành trước khi A có thể tiếp tục.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><label class="field">Công việc phụ thuộc<select name="issue_id" required><?php foreach($issues as $i):?><option value="<?=$i['id']?>">#<?=$i['id']?> · <?=h($i['title'])?></option><?php endforeach;?></select></label><label class="field">Phải hoàn thành trước (B)<select name="depends_on_id" required><?php foreach($issues as $i):?><option value="<?=$i['id']?>">#<?=$i['id']?> · <?=h($i['title'])?></option><?php endforeach;?></select></label><button>Kiểm tra và thêm</button></form></section><section class="panel"><h2>Đang chặn tiến độ</h2><?php if(!$blocked):?><p>Không có quan hệ nào đang chặn theo trạng thái hiện tại.</p><?php else:?><ul><?php foreach($blocked as $b):?><li>#<?=$b['id']?> <?=h($b['title'])?> đang chờ #<?=$b['blocked_by_id']?> <?=h($b['blocked_by'])?></li><?php endforeach;?></ul><?php endif;?></section><section class="panel"><h2>Quan hệ đã khai báo (<?=count($deps)?>)</h2><ul><?php foreach($deps as $d):?><li>#<?=$d['issue_id']?> <?=h($d['issue_title'])?> phụ thuộc #<?=$d['depends_on_id']?> <?=h($d['dependency_title'])?> <span class="pill"><?=h($d['dependency_status'])?></span></li><?php endforeach;?></ul></section><?php pageEnd(); ?>